{#- Signed record (URS-CMP-003): the record as stored and the signatures on it. Field values are rendered as Frappe's standard print renders them (Frappe sanitises HTML when a record is saved); names and reasons are escaped here. -#}
<style>
	.mds-signed { font-size: 11px; }
	.mds-signed .mds-note { color: #555; margin-bottom: 10px; }
	.mds-signed table { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
	.mds-signed th, .mds-signed td { border: 1px solid #c8c8c8; padding: 4px 6px; text-align: left; vertical-align: top; }
	.mds-signed th { background: #f4f4f4; }
	.mds-signed table.mds-fields th { width: 28%; }
</style>
<div class="mds-signed">
	<h3>{{ _(doc.doctype) }} {{ doc.name | e }}</h3>
	<p class="mds-note">{{ _("Printed on {0} by {1}").format(frappe.utils.format_datetime(frappe.utils.now_datetime()), frappe.session.user | e) }}{% if doc.docstatus == 0 %} · <strong>{{ _("DRAFT – not signed") }}</strong>{% elif doc.docstatus == 2 %} · <strong>{{ _("CANCELLED") }}</strong>{% endif %}</p>
	<table class="mds-fields">
	{%- for df in doc.meta.fields if df.fieldtype not in ("Section Break", "Column Break", "Tab Break", "HTML", "Button", "Table", "Table MultiSelect", "Attach Image") and not df.print_hide and not df.hidden and doc.get(df.fieldname) not in (None, "") %}
		<tr><th>{{ _(df.label) }}</th><td>{{ doc.get_formatted(df.fieldname) }}</td></tr>
	{%- endfor %}
	</table>
	{%- for df in doc.meta.fields if df.fieldtype in ("Table", "Table MultiSelect") and not df.print_hide and doc.get(df.fieldname) %}
	{%- set columns = doc.get(df.fieldname)[0].meta.fields | selectattr("in_list_view") | list %}
	<h4>{{ _(df.label) }}</h4>
	<table>
		<tr>{% for c in columns %}<th>{{ _(c.label) }}</th>{% endfor %}</tr>
		{%- for row in doc.get(df.fieldname) %}
		<tr>{% for c in columns %}<td>{{ row.get_formatted(c.fieldname) }}</td>{% endfor %}</tr>
		{%- endfor %}
	</table>
	{%- endfor %}
	<h4>{{ _("Electronic signatures") }}</h4>
	{%- set signatures = signatures_for_print(doc) %}
	{%- if signatures %}
	<table>
		<tr><th>{{ _("Meaning") }}</th><th>{{ _("Act") }}</th><th>{{ _("Signed by") }}</th><th>{{ _("Date and time") }}</th><th>{{ _("Reason") }}</th></tr>
		{%- for s in signatures %}
		<tr><td>{{ _(s.meaning) }}</td><td>{{ _(s.action) }}</td><td>{{ s.signer_name | e }} ({{ s.signer | e }})</td><td>{{ frappe.utils.format_datetime(s.signed_at) }}</td><td>{{ (s.reason or "") | e }}</td></tr>
		{%- endfor %}
	</table>
	{%- else %}
	<p>{{ _("Not signed.") }}</p>
	{%- endif %}
</div>
